}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since we are minimizing the number of containers and it is acceptable to leave goods unshipped, is the goal simply to ship as much as possible (or all goods) using the fewest containers, or is it to ship any feasible amount (even just enough to fill one container) using the fewest containers?"
  ],
  "rationale": "The response contains a single clarification question asking for a choice between two specific optimization objectives (maximize shipment volume vs. minimize container count regardless of volume)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Which is it — must all 120 A, 90 B, 300 C, 90 D, and 120 E units be shipped, or is leaving some unshipped still allowed?"
  ],
  "rationale": "The response asks for a single policy clarification regarding whether all units must be shipped or if some can be left unshipped. Although it lists multiple product types, the core question is a single binary choice about the shipping policy."
}

{
  "action": "question",
  "question_count": 1,
